const BY_SLUG = new Map(CATALOG.map((e) => [e.slug, e]));

/** Look up a catalogue entry. Returns undefined for custom (non-catalogue) exercises. */
export function catalogExercise(slug: string | null | undefined): CatalogExercise | undefined {
  return slug ? BY_SLUG.get(slug) : undefined;
}

/** Path to one frame's figure. `frame` is 1-based. */
export function figureUrl(slug: string, frame = 1): string {
  return `/exercises/${slug}/${frame}.png`;
}
